CREATE TABLE `items` (
  `itemId` int(11) NOT NULL AUTO_INCREMENT,
  `itemType` text DEFAULT NULL,
  `catalogType` text DEFAULT NULL,
  `modelType` int(11) DEFAULT NULL,
  `creatorId` int(11) DEFAULT NULL,
  `creatorName` text DEFAULT NULL,
  `itemName` text DEFAULT 'Place',
  `fileName` text DEFAULT NULL,
  `itemDescription` text DEFAULT NULL,
  `onsale` int(11) NOT NULL DEFAULT 0,
  `commentsEnabled` int(11) NOT NULL DEFAULT 1,
  `priceInTix` int(11) DEFAULT 0,
  `priceInBoombux` int(11) DEFAULT NULL,
  `favorites` int(64) NOT NULL DEFAULT 0,
  `interactions` int(64) NOT NULL DEFAULT 0,
  `status` text NOT NULL DEFAULT 'pending',
  `lastUpdate` timestamp NOT NULL DEFAULT current_timestamp(),
  `creationDate` timestamp NOT NULL DEFAULT current_timestamp(),
  `port` int(11) DEFAULT NULL,
  `JobId` varchar(255) DEFAULT NULL,
  `serverstatus` varchar(255) DEFAULT 'stopped',
  `respawncd` int(11) DEFAULT NULL,
  `playersMax` int(11) NOT NULL DEFAULT 8,
  `access` int(11) NOT NULL DEFAULT 1,
  `boombloxifier` int(11) NOT NULL DEFAULT 0,
  `versionId` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`itemId`)
) ENGINE=InnoDB AUTO_INCREMENT=2426 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
