INSERT INTO `threads` VALUES (1,NULL,0,3,'test pin thread','hi this is a test','2024-11-02 02:32:09','2025-11-30 21:13:46',13,1,'a:2:{i:0;i:3;i:1;i:100;}'),(2,NULL,0,3,'test thread','hi this is a test #2','2024-11-02 02:32:18','2025-11-30 21:13:48',13,0,'a:2:{i:0;i:3;i:1;i:100;}'),(3,NULL,0,3,'first post of 2025','this would be really cool if it works','2025-12-07 06:11:37','2025-12-07 06:11:37',13,0,'a:0:{}'),(4,NULL,0,79,'Hello','Hello people!','2025-12-07 06:16:17','2025-12-07 06:16:17',13,0,'a:0:{}'),(5,4,1,79,'it works','this is amazing','2025-12-07 06:21:13','2025-12-06 23:37:54',13,0,'a:0:{}'),(6,4,1,3,'RE: Hello','i wonder if this reply will reply','2025-12-07 06:34:29','2025-12-06 23:37:47',13,0,'a:0:{}'),(7,4,1,3,'RE: Hello test 2','aaaaa','2025-12-07 06:38:03','2025-12-07 06:38:03',13,0,'a:0:{}'),(8,NULL,0,3,'off topic post','i will probably continue to use this for forum testing','2025-12-07 06:58:16','2025-12-07 06:58:16',13,0,'a:0:{}'),(9,8,1,3,'RE off topic post','this infact did not go to off topic','2025-12-07 06:58:34','2025-12-07 06:58:34',13,0,'a:0:{}'),(10,NULL,0,3,'first off topic for real this time','will this work','2025-12-07 06:59:51','2025-12-07 06:59:51',18,0,'a:0:{}'),(11,10,1,3,'RE first off topic for real this time','hey this actually works','2025-12-07 07:00:05','2025-12-07 07:00:05',18,0,'a:0:{}'),(12,NULL,0,3,'test count post','this should update the forum screen','2025-12-07 07:12:35','2025-12-07 07:12:35',13,0,'a:0:{}'),(13,NULL,0,100,'hello','hi','2025-12-07 07:23:24','2025-12-07 07:23:24',13,0,'a:0:{}'),(14,NULL,0,100,'Dark theme doesn\'t work here in the forums','ik this bcuz i\'m using dark theme rn','2025-12-07 07:30:05','2025-12-07 07:30:05',14,0,'a:0:{}'),(15,NULL,0,100,'Another technical problem','I cannot see ANYTHING besides the highlighted words in the admin panel when using dark mode.','2025-12-07 07:31:01','2025-12-07 07:31:01',14,0,'a:0:{}'),(16,NULL,0,100,'Friend request bug.','When accepting a friend request via ac